B=256; M0=3*2^(B-2); BL=521; ML=3*2^(BL-2);
cd(a,b)=-((-a)\b);
S=sqrtint(M0); a=sqrtint(S); d1=nextprime(a); d2=nextprime(d1+1); D=d1*d2; u0=cd(M0,2*D);
u=u0; while(!(ispseudoprime(u) && u!=d1 && u!=d2 && ispseudoprime(2*D*u+1) && (2*D*u+2)%12==0 && ispseudoprime((2*D*u+2)/12)), u++);
rM=2*D*u+1;
print("PLANTM d1=",d1," d2=",d2," u0=",u0," u=",u," r=",rM," cands_d1=",cnt(a,d1)," cands_d2=",cnt(d1+1,d2)," cands_u=",u-u0+1," proof=",isprime(u,2)*isprime(rM,2)*isprime((rM+1)/12,2)*isprime(d1,2)*isprime(d2,2));
d0=sqrtnint(M0/4,3); dP=nextprime(d0); w0=cd(M0,12*dP);
w=w0; while(!(ispseudoprime(w) && w!=dP && ispseudoprime(12*dP*w-1) && ispseudoprime((12*dP*w-2)/2)), w++);
rP=12*dP*w-1;
print("PLANTP d0=",d0," d=",dP," w0=",w0," w=",w," r=",rP," cands_d=",cnt(d0,dP)," cands_w=",w-w0+1," proof=",isprime(dP,2)*isprime(w,2)*isprime(rP,2)*isprime((rP-1)/2,2));
w0=2^(B-4); w=w0; while(!(ispseudoprime(w) && ispseudoprime(12*w-1) && ispseudoprime(6*w-1)), w++);
rI=12*w-1;
print("INERT w0=",w0," w=",w," r=",rI," cands_w=",w-w0+1," proof=",isprime(w,2)*isprime(rI,2)*isprime(6*w-1,2));
xL=sqrtnint(ML/4,3); f1=nextprime(2^43); f2=nextprime(f1+1); f3=nextprime(f2+1); G=f1*f2*f3; y=cd(xL,G); f4=nextprime(y); DL=G*f4; w0=cd(ML,12*DL);
w=w0; while(!(ispseudoprime(w) && ispseudoprime(12*DL*w-1) && ispseudoprime(6*DL*w-1)), w++);
rL=12*DL*w-1;
print("PLANTPL xL=",xL," f1=",f1," f2=",f2," f3=",f3," f4=",f4," w0=",w0," w=",w," r=",rL," cands=",[cnt(2^43,f1),cnt(f1+1,f2),cnt(f2+1,f3),cnt(y,f4),w-w0+1]," bits=",#binary(rL));
print("PLANTPL_proof=",isprime(f1,2)*isprime(f2,2)*isprime(f3,2)*isprime(f4,2)*isprime(w,2)*isprime(rL,2)*isprime((rL-1)/2,2));
print("CF1_proof=",isprime(2^255-19,2)," CF2_proof=",isprime(2^256-2^224+2^192+2^96-1,2));
quit;

