#!/usr/bin/env python3
"""TASK-20260926-b99738 J1(i): follow each PR-* parse rule of
AMD-20260926-typed change.D1_pins literally. Python 3.9 stdlib (re)."""
import re, json, hashlib, sys
WS = '\u0009\u000a\u000b\u000c\u000d\u0020\u0085\u00a0'
def strip_ws(s): return s.strip(WS)
def rm_ws(s, bs=True):
    s = ''.join(c for c in s if c not in WS)
    return s.replace('\\', '') if bs else s
def lines_of(path):
    return open(path, 'rb').read().decode('utf-8', 'strict').split('\n')
HEX = set('0123456789abcdefABCDEF'); DEC = set('0123456789')
CHOICES = []  # every point where the text left the implementation a choice

def pr_sp800(path, section, label):
    L = lines_of(path)
    start = next(i for i, l in enumerate(L) if strip_ws(l) == section)
    end = next((i for i in range(start + 1, len(L)) if re.match(r'^[0-9]+(\.[0-9]+)*\.$', strip_ws(L[i]))), len(L))
    blk = list(range(start, end))
    lab = next((i for i in blk if L[i].lstrip(WS).startswith(label + ':')), None)
    if lab is None: return dict(result='locator_failure', why='no label line')
    col = L[lab].index(label + ':') + len(label) + 1
    # text stream from after "L:" to end of block, with line indices
    stream = []  # (lineidx, char)
    for c in L[lab][col:]: stream.append((lab, c))
    stream.append((lab, '\n'))
    nxt_label_line = None
    for i in range(lab + 1, end):
        if nxt_label_line is None and re.match(r'^[A-Za-z]{1,4}:', strip_ws(L[i])):
            nxt_label_line = i
        for c in L[i]: stream.append((i, c))
        stream.append((i, '\n'))
    # (a) first "(" after "L:" ; (b) start of next label line
    pos_a = next((k for k, (i, c) in enumerate(stream) if c == '('), None)
    pos_b = next((k for k, (i, c) in enumerate(stream) if nxt_label_line is not None and i == nxt_label_line), None)
    cands = [p for p in (pos_a, pos_b) if p is not None]
    if not cands: return dict(result='locator_failure', why='span unterminated')
    endpos = min(cands); ended_by = 'a' if endpos == pos_a else 'b'
    span = ''.join(c for _, c in stream[:endpos])
    span_lines = sorted({i + 1 for i, _ in stream[:endpos]})
    dec = rm_ws(span)
    dec_clean = bool(dec) and set(dec) <= DEC
    hexv = None; hex_clean = False; hex_str = None
    if ended_by == 'a':
        rest = ''.join(c for _, c in stream[endpos + 1:])
        rest_nows = rm_ws(rest, bs=False)
        if rest_nows[:3] == '=0x':
            # from after "=0x" to first ")" after it (in raw text)
            k = rest.index('0x') + 2  # first "=0x" once ws removed; locate raw
            # locate raw position of "=0x": walk
            raw = rest; j = 0; seen = ''
            while len(seen) < 3:
                if raw[j] not in WS: seen += raw[j]
                j += 1
            close = raw.index(')', j)
            hex_str = rm_ws(raw[j:close], bs=False)
            hex_clean = bool(hex_str) and set(hex_str) <= HEX
            span_lines = sorted(set(span_lines) | {stream[endpos + 1 + t][0] + 1 for t in range(close + 1)})
            if hex_clean: hexv = int(hex_str, 16)
    ignored = []
    if hexv is not None:
        V = hexv; rep = 'hex'
        if dec_clean:
            if len(dec) == len(str(V)):
                if int(dec) != V: return dict(result='locator_failure', why='hex/dec mismatch')
            else:
                ignored.append(('decimal', 'decimal_span_not_a_literal'))
        else:
            ignored.append(('decimal', 'contaminated'))
    elif dec_clean:
        V = int(dec); rep = 'decimal'
        if hex_str is not None: ignored.append(('hex', 'contaminated'))
    else:
        return dict(result='locator_failure', why='neither clean', dec=dec[:80], hex=hex_str)
    return dict(result='ok', value=V, representation=rep, ended_by=ended_by, label_line=lab + 1,
                lines=[min(span_lines), max(span_lines)], ignored=ignored, dec_form=dec if dec_clean else None,
                hex_form=hex_str if hex_clean else None, block=[start + 1, end])

def pr_sec2(path, curve, label):
    L = lines_of(path)
    start = next((i for i, l in enumerate(L) if re.match(r'^[0-9]+(\.[0-9]+)+RecommendedParameters' + curve + '$', rm_ws(l, bs=False))), None)
    if start is None: return dict(result='locator_failure', why='no block')
    end = next((i for i in range(start + 1, len(L)) if 'RecommendedParameters' in L[i]), len(L))
    lab = None
    for i in range(start, end):
        if strip_ws(L[i]) == label:
            j = i + 1
            while j < end and strip_ws(L[j]) == '': j += 1
            if j < end and L[j].lstrip(WS).startswith('='):
                lab = (i, j); break
    if lab is None: return dict(result='locator_failure', why='no label')
    i, j = lab
    after = rm_ws(L[j].lstrip(WS)[1:], bs=False)
    vals = []
    if after:
        first = j
        vals.append(after)
    else:
        first = j + 1
        while first < end and strip_ws(L[first]) == '': first += 1
        vals.append(rm_ws(L[first], bs=False))
    if not (vals[0] and set(vals[0]) <= HEX): return dict(result='locator_failure', why='first value line not hex', line=first + 1, text=L[first])
    k = first + 1; last = first
    while k < end:
        s = rm_ws(L[k], bs=False)
        if s and set(s) <= HEX and len(s) >= 4:
            vals.append(s); last = k; k += 1
        else:
            break
    return dict(result='ok', value=int(''.join(vals), 16), hex_form=''.join(vals), label_line=i + 1,
                lines=[first + 1, last + 1], block=[start + 1, end], stop_line=(k + 1, L[k] if k < len(L) else None))

def pr_rfc5639(path, curve, label):
    L = lines_of(path)
    start = next((i for i, l in enumerate(L) if strip_ws(l) == 'Curve-ID: ' + curve), None)
    if start is None: return dict(result='locator_failure', why='no block')
    end = next((i for i in range(start + 1, len(L)) if strip_ws(L[i]).startswith('Curve-ID:') or strip_ws(L[i]).startswith('#Twisted') or re.match(r'^[0-9]+(\.[0-9]+)*\.\s', strip_ws(L[i]))), len(L))
    lab = next((i for i in range(start, end) if strip_ws(L[i]).startswith(label + ' =') or strip_ws(L[i]) == label + ' ='), None)
    if lab is None: return dict(result='locator_failure', why='no label')
    parts = [L[lab][L[lab].index('=') + 1:]]
    k = lab + 1
    while k < end:
        s = strip_ws(L[k])
        if s and set(rm_ws(s, bs=False)) <= HEX:
            parts.append(L[k]); k += 1
        else: break
    h = rm_ws(''.join(parts), bs=False)
    if not (h and set(h) <= HEX): return dict(result='locator_failure', why='non-hex', text=h[:80])
    return dict(result='ok', value=int(h, 16), hex_form=h, label_line=lab + 1, lines=[lab + 1, k], block=[start + 1, end])

def pr_rfc7748(path, label):
    L = lines_of(path)
    start = next(i for i, l in enumerate(L) if strip_ws(l) == '4.1.  Curve25519')
    end = next((i for i in range(start + 1, len(L)) if re.match(r'^[0-9]+(\.[0-9]+)*\.\s', strip_ws(L[i]))), len(L))
    lab = next((i for i in range(start, end) if re.match('^' + re.escape(label) + '[' + re.escape(WS) + ']', strip_ws(L[i]))), None)
    if lab is None: return dict(result='locator_failure', why='no label')
    rem = rm_ws(strip_ws(L[lab])[len(label):], bs=False)
    m1 = re.fullmatch(r'2\^([0-9]+)\+0x([0-9A-Fa-f]+)', rem); m2 = re.fullmatch(r'2\^([0-9]+)-([0-9]+)', rem)
    if m1: v = 2 ** int(m1.group(1)) + int(m1.group(2), 16)
    elif m2: v = 2 ** int(m2.group(1)) - int(m2.group(2))
    else: return dict(result='locator_failure', why='form', text=rem)
    return dict(result='ok', value=v, expression=rem, label_line=lab + 1, block=[start + 1, end])

if __name__ == '__main__':
    S = '/tmp/b99738/src/'
    out = {}
    for rid, sec in [('NIST-P-224', '3.2.1.2.'), ('NIST-P-256', '3.2.1.3.'), ('NIST-P-384', '3.2.1.4.'), ('NIST-P-521', '3.2.1.5.'), ('Ed25519-L', '3.2.3.1.')]:
        out[rid] = {lab: pr_sp800(S + 'sp800-186.txt', sec, lab) for lab in ('n', 'p', 'h')}
    for rid, cv in [('NIST-P-224', 'secp224r1'), ('NIST-P-256', 'secp256r1'), ('NIST-P-384', 'secp384r1'), ('NIST-P-521', 'secp521r1'), ('secp256k1', 'secp256k1')]:
        out.setdefault(rid, {})['sec2'] = {lab: pr_sec2(S + 'sec2-v2.txt', cv, lab) for lab in ('n', 'p', 'h')}
    for rid in ('brainpoolP256r1', 'brainpoolP384r1'):
        out[rid] = {lab: pr_rfc5639(S + 'rfc5639.txt', rid, lab) for lab in ('q', 'p', 'h')}
    out['Ed25519-L']['rfc7748'] = {lab: pr_rfc7748(S + 'rfc7748.txt', lab) for lab in ('order', 'p')}
    def conv(o):
        if isinstance(o, dict): return {k: conv(v) for k, v in o.items()}
        if isinstance(o, (list, tuple)): return [conv(v) for v in o]
        if isinstance(o, int) and not isinstance(o, bool) and o > 2 ** 53: return {'dec': str(o), 'hex': hex(o)}
        return o
    json.dump(conv(out), open('/tmp/b99738/pins_out.json', 'w'), indent=1)
    for rid, d in out.items():
        for k, v in d.items():
            if 'result' in v:
                print(rid, k, v['result'], v.get('representation', ''), v.get('ended_by', ''), (hex(v['value'])[:20] if 'value' in v else v.get('why')), v.get('ignored', ''), v.get('lines', ''))
            else:
                for kk, vv in v.items():
                    print(rid, k, kk, vv['result'], (hex(vv['value'])[:20] if 'value' in vv else vv.get('why')), vv.get('lines', ''), vv.get('stop_line', ''))

