    rows[rid]=dict(r=v(P[rid]['n']),p=v(P[rid]['p']),h=v(P[rid]['h']))
rows['secp256k1']=dict(r=v(P['secp256k1']['sec2']['n']),p=v(P['secp256k1']['sec2']['p']),h=v(P['secp256k1']['sec2']['h']))
