for rid,x in rows.items(): FP.add(x['p'])
for rid,x in rows.items():
    r,p,h=x['r'],x['p'],x['h']
    c=dict(r_bits=r.bit_length(),p_bits=p.bit_length(),h=h,r_prime=is_prime(r),p_prime=is_prime(p),
      hasse=abs(p+1-h*r)<=2*isqrt(p)+2, r_in_FP=r in FP)
