import re, json, hashlib
from math import isqrt
exec(open('/tmp/b99738/build_controls.py').read().split('out = {}')[0])
WS='\u0009\u000a\u000b\u000c\u000d\u0020\u0085\u00a0'
def pr_ietf(path, label):
    L=open(path,'rb').read().decode('utf-8','strict').split('\n')
    st=next((i for i,l in enumerate(L) if re.match(r'^[0-9]+(\.[0-9]+)*\.\s.*\(BLS12-381\)$', l.strip(WS))),None)
    if st is None: return dict(result='locator_failure',why='no block')
    en=next((i for i in range(st+1,len(L)) if re.match(r'^[0-9]+(\.[0-9]+)*\.\s', L[i].strip(WS))),len(L))
    lab=None
    for i in range(st,en):
        s=L[i].strip(WS)
        if s.startswith('*'): s=s[1:].lstrip(WS)
        if re.match('^'+label+r'\s*[:=]', s): lab=i; break
    if lab is None: return dict(result='locator_failure',why='no label')
    s=L[lab]; k=min([x for x in (s.find(':'),s.find('=')) if x>=0])
    vt=[s[k+1:]]; j=lab+1
    allowed=re.compile(r'^(?:[0-9A-Fa-f]|0x|x|\^|\+|-|['+re.escape(WS)+'])+$')
    while j<en:
        ss=L[j].strip(WS)
        if ss and allowed.match(ss): vt.append(L[j]); j+=1
        else: break
    v=''.join(c for c in ''.join(vt) if c not in WS)
    if re.fullmatch(r'-?0x[0-9A-Fa-f]+',v): val=int(v,16)
    elif re.fullmatch(r'-?[0-9]+',v): val=int(v)
    elif re.fullmatch(r'-?2\^[0-9]+([+-]2\^[0-9]+)*',v):
        val=0
        for sg,e in re.findall(r'(-?|\+|-)2\^([0-9]+)', v): val+= -2**int(e) if sg=='-' else 2**int(e)
    else: return dict(result='locator_failure',why='form',text=v[:80])
    return dict(result='ok',value=val,text=v,block=[st+1,en],label_line=lab+1,lines=[lab+1,j])
out={}
for rev in ['draft-14.txt','draft-13.txt','draft-11.txt']:
    P='/tmp/b99738/src/'+rev
    R={l:pr_ietf(P,l) for l in ('p','r','h','t')}
    if all(x['result']=='ok' for x in R.values()):
        p,r,h,t=(R[l]['value'] for l in ('p','r','h','t'))
        num=(t-1)**2*(t**4-t**2+1)
        fam=dict(r_eq=r==t**4-t**2+1, p_div_exact=num%3==0, p_eq=(num%3==0 and p==num//3+t),
                 hasse=abs(p+1-h*r)<=2*isqrt(p)+2, r_prime=is_prime(r), p_prime=is_prime(p), r_bits=r.bit_length(), p_bits=p.bit_length(), r_hex=hex(r))
    else: fam=None
    out[rev]=dict(sha256=hashlib.sha256(open(P,'rb').read()).hexdigest(),
                  parse={l:{k:(hex(v) if isinstance(v,int) and not isinstance(v,bool) else v) for k,v in x.items()} for l,x in R.items()},family=fam)
    print(rev, {l:(x['result'],x.get('lines'),x.get('text','')[:24]) for l,x in R.items()}, fam)
json.dump(out,open('/tmp/b99738/pin_bls.json','w'),indent=1)

