import sys, json, hashlib, pypdf
from pypdf import PdfReader
WS='\u0009\u000a\u000b\u000c\u000d\u0020\u0085\u00a0'
def norm(path):
    t="\n".join(page.extract_text() for page in PdfReader(path).pages)
    t=''.join(c for c in t if c not in WS).replace('\\','').lower()
    return t
P=json.load(open('/tmp/b99738/pins_out.json'))
S='/tmp/b99738/src/'
out={'pypdf':pypdf.__version__}
for pdf in ('sp800-186.pdf','sec2-v2.pdf'):
    n=norm(S+pdf); out[pdf+'_normalized_sha256']=hashlib.sha256(n.encode()).hexdigest(); out[pdf+'_len']=len(n)
    out[pdf+'_contains_discretelogarithm']='discretelogarithm' in n
    if pdf=='sp800-186.pdf':
        for rid in ['NIST-P-224','NIST-P-256','NIST-P-384','NIST-P-521','Ed25519-L']:
            for lab in ('n','p','h'):
                x=P[rid][lab]; s=(x.get('hex_form') if x.get('representation')=='hex' else x.get('dec_form'))
                out[f'{rid}.{lab}']=dict(form=x.get('representation'),digits=len(s),PASS=s.lower() in n)
    else:
        for rid in ['NIST-P-224','NIST-P-256','NIST-P-384','NIST-P-521','secp256k1']:
            for lab in ('n','p','h'):
                s=P[rid]['sec2'][lab]['hex_form']
                out[f'{rid}.sec2.{lab}']=dict(digits=len(s),PASS=s.lower() in n)
print(json.dumps(out,indent=0))

