#!/usr/bin/env python3
"""Path-A style producer (reviewer's own) using PARI through cypari2: ECPP via
primecert for p >= 2^64, Pratt for p < 2^64 and for the terminal prime."""
import json, sys, cypari2
pari = cypari2.Pari()
pari.allocatemem(2*10**9, silent=True) if False else pari.allocatemem(2*10**9)

def pratt(p):
    if p == 2: return None
    fac = pari.factor(p - 1)
