from AMD-20260926-typed change.D7_certificates.independent_verifier text.
Imports ONLY the Python standard library (json, math, sys)."""
import json, sys
from math import gcd

def pratt_ok(p, cert):
    """cert = {'p': p, 'a': a, 'factors': [[f, k, subcert_or_None], ...]}; leaf 2."""
    if p == 2: return True
    if cert['p'] != p: return False
    prod = 1
    for f, k, _ in cert['factors']: prod *= f ** k
    if prod != p - 1: return False
    a = cert['a']
    if pow(a, p - 1, p) != 1: return False
    for f, k, sub in cert['factors']:
        if pow(a, (p - 1) // f, p) == 1: return False
        if f != 2 and not pratt_ok(f, sub): return False
    return True

def inv(x, N):
    g = gcd(x % N, N)
    if g != 1: raise ValueError('non-invertible')
    return pow(x, -1, N)

def ec_add(P, Q, a4, N):
    if P is None: return Q
    if Q is None: return P
    x1, y1 = P; x2, y2 = Q
    if (x1 - x2) % N == 0:
        if (y1 + y2) % N == 0: return None
        lam = (3 * x1 * x1 + a4) * inv(2 * y1, N) % N
    else:
        lam = (y2 - y1) * inv(x2 - x1, N) % N
    x3 = (lam * lam - x1 - x2) % N
    return (x3, (lam * (x1 - x3) - y1) % N)

def ec_mul(k, P, a4, N):
    R = None
    for bit in bin(k)[2:]:
        R = ec_add(R, R, a4, N)
        if bit == '1': R = ec_add(R, P, a4, N)
    return R

def icbrt4_c(N):
    c = 1
    while c ** 4 < N: c *= 2
    lo, hi = c // 2, c
    while lo < hi:
        mid = (lo + hi) // 2
        if mid ** 4 >= N: hi = mid
        else: lo = mid + 1
    return lo

def ecpp_step_ok(N, t, s, a4, P):
    if gcd(N, 6) != 1: return False, None
    m = N + 1 - t
    if s <= 0 or m % s: return False, None
    q = m // s
    x, y = P[0] % N, P[1] % N
    b = (y * y - x ** 3 - a4 * x) % N
    if gcd((4 * a4 ** 3 + 27 * b * b) % N, N) != 1: return False, None
    try:
        S = ec_mul(s, (x, y), a4, N)        # [s]P must be affine, denominators invertible
        if S is None: return False, None
        Qm1 = ec_mul(q - 1, S, a4, N)       # [m]P = O  <=>  [q-1]([s]P) = -[s]P
        if Qm1 is None or Qm1[0] != S[0] or (Qm1[1] + S[1]) % N != 0: return False, None
    except ValueError:
        return False, None
    c = icbrt4_c(N)
    if not q > (c + 1) ** 2: return False, None
    return True, q

def verify(cert):
    p = cert['p']
    if cert['kind'] == 'pratt':
        return pratt_ok(p, cert['pratt'])
    steps = cert['ecpp']
    if steps[0][0] != p: return False
    q = None
    for i, (N, t, s, a4, P) in enumerate(steps):
        if i > 0 and N != q: return False
        ok, q = ecpp_step_ok(N, t, s, a4, P)
        if not ok: return False
    return cert['terminal']['p'] == q and pratt_ok(q, cert['terminal'])

def smallest_strong_witness_ok(C, a):
    if C % 2 == 0: return a == 'even'
    d = C - 1; s = 0
    while d % 2 == 0: d //= 2; s += 1
    def fails(b):
        x = pow(b, d, C)
        if x in (1, C - 1): return False
        for _ in range(s - 1):
            x = x * x % C
            if x == C - 1: return False
        return True
    return fails(a) and all(not fails(b) for b in range(2, a))

if __name__ == '__main__':
    for path in sys.argv[1:]:
        c = json.load(open(path), parse_int=int)
        print(path, 'ACCEPT' if verify(c) else 'REJECT')
